/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, DiracDelta, Heaviside, Mul, Pow, Sym, SymFunction, add, changeMul, deltaintegrate, fn, mul, pi, pow, rational, symbols } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.integrals.deltafunctions", () => {
  it("change_mul(x*y*DiracDelta(x)*cos(x), x)", () => {
    const [x, y] = symbols('x y');
    const v1 = DiracDelta(x);
    expect(sympyMatches([v1, at(changeMul(mul(x, y, v1, fn('cos', [x])), x), 1)], '(DiracDelta(x), x*y*cos(x))')).toBe(true);
  });
  // a primitive result that no library call returned
  //   change_mul(x*y*DiracDelta(x**2 - 1)*cos(x), x)
  //   => (None, x*y*cos(x)*DiracDelta(x - 1)/2 + x*y*cos(x)*DiracDelta(x + 1)/2)
  it.todo("change_mul(x*y*DiracDelta(x**2 - 1)*cos(x), x)");
  // a primitive result that no library call returned
  //   change_mul(x*y*DiracDelta(cos(x))*cos(x), x)
  //   => (None, None)
  it.todo("change_mul(x*y*DiracDelta(cos(x))*cos(x), x)");
  it("deltaintegrate(x*sin(x)*cos(x)*DiracDelta(x - 1), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(deltaintegrate(mul(x, DiracDelta(add(-1, x)), fn('cos', [x]), fn('sin', [x])), x))).toBe('sin(1)*cos(1)*Heaviside(x - 1)');
  });
  it("deltaintegrate(y**2*DiracDelta(x - z)*DiracDelta(y - z), y)", () => {
    const [y, x, z] = symbols('y x z');
    expect(sympyStr(deltaintegrate(mul(pow(y, 2), DiracDelta(add(x, mul(-1, z))), DiracDelta(add(y, mul(-1, z)))), y))).toBe('z**2*DiracDelta(x - z)*Heaviside(y - z)');
  });
});

